#!/usr/bin/env bash
# «Жазыл» жобасының алғашқы 16 тапсырмасын GitHub-та жасайды.
# Талап: GitHub CLI (https://cli.github.com) орнатылған және `gh auth login` орындалған.
# Тақтаға автоматты қосу үшін: `gh auth refresh -s project` және тақтаның атауы «Жазыл» болуы керек.
# Іске қосу: репозиторий түбірінде `bash scripts/create_issues.sh`
set -e
PROJECT="Жазыл"

for l in "story:0E8A16" "tech:5319E7" "docs:1D76DB" "risk:D93F0B" "bug:B60205" "research:FBCA04"; do
  gh label create "${l%%:*}" --color "${l##*:}" --force >/dev/null
done

mk() { gh issue create --title "$1" --label "$2" --body "$3" --project "$PROJECT"; }

mk "ZHL-1 Репозиторий құрылымын жасау (docs/, src/, tests/)" tech "Методичканың 1.1-бөліміндегі каталогтар құрылымы. Дайын: каталогтар main-де."
mk "ZHL-2 ADR-001: жеткізу моделін таңдау" docs "docs/adr/0001-delivery-model.md, MADR үлгісі, кемінде 2 қабылданбаған нұсқа және салдары."
mk "ZHL-3 Тақтаны баптау: статустар, өрістер, тапсырма шаблондары" tech "Статустар: Backlog, Ready, In progress, Review, Blocked, Done. Өрістер: Size, Owner, Iteration, Risk ID."
mk "ZHL-4 Вики беттері (docs/wiki)" docs "Жоба туралы, Глоссарий, Жұмыс процесі, Байланыстар, Шешімдер журналы, Тапсыру журналы."
mk "ZHL-5 Бизнес иесімен алғашқы кездесу және жазылулар ағынын өлшеу" research "Аптасына қанша жазылу түседі, қаншасы келмей қалады, иесі жазылуларды жүргізуге қанша уақыт жұмсайды, айына неше рет бір уақытқа екі жазылу болады. Нәтиже — бастапқы метрикалар."
mk "ZHL-6 R-1: жобаға аптасына 4 сағаттан аз уақыт бөліну тәуекелі" risk "Егер басқа пәндердің жүктемесінен жобаға аптасына < 4 сағ қалса, онда вехалар жылжиды. Триггер: қатарынан 2 апта жоспардың < 50 %-ы жабылды."
mk "ZHL-7 R-2: бизнес иесінің уақыты шектеулі болу тәуекелі" risk "Егер бизнес иесі сұрауға 7 күн ішінде жауап бермесе, онда талаптар мен қабылдау кешігеді."
mk "ZHL-8 Бизнес-кейс және TCO (3-ЗЖ)" docs "Мәселе цифрмен, кемінде 4 нұсқа (оның ішінде «ештеңе істемеу» және дайын онлайн-жазылу сервисін сатып алу), 3 жылдық TCO, ROI, сезімталдық талдауы."
mk "ZHL-9 Жоба жарғысы (3-ЗЖ)" docs "1–2 бет: мақсаттар, «кіреді / кірмейді», жорамалдар, шектеулер, вехалар, эскалация шегі."
mk "ZHL-10 Клиент ретінде қызмет пен бос уақытты таңдап, онлайн жазылғым келеді, қоңырау шалмау үшін" story "Given: клиент жазылу бетін ашты. When: қызметті, күнді және бос слотты таңдап, атын және телефонын енгізіп жіберді. Then: жазылу сақталды, растау көрсетілді, бұл слот басқаларға бос емес болып көрінеді. Теріс: таңдалған слотты осы сәтте басқа клиент алып қойса — жазылу сақталмайды, клиентке басқа уақыт ұсынылады."
mk "ZHL-11 Клиент ретінде жазылудан 1 күн бұрын еске салғыш алғым келеді, ұмытып қалмау үшін" story "Given: ертеңге расталған жазылу бар. When: жазылуға 24 сағат қалды. Then: клиентке Telegram немесе пошта арқылы күні, уақыты және бас тарту сілтемесі бар хабарлама келді. Теріс: хабарлама жіберілмесе — қате журналға жазылады, жазылу өзгермейді."
mk "ZHL-12 Бизнес иесі ретінде күндік жазылуларды күнтізбеден көргім келеді, дәптер жүргізбеу үшін" story "Given: күнге бірнеше жазылу бар. When: иесі күнтізбені ашады. Then: жазылулар уақыт бойынша көрсетілген, әрқайсысында клиенттің аты, телефоны және қызмет бар."
mk "ZHL-13 Бизнес иесі ретінде қызметтер мен жұмыс кестесін баптағым келеді, жұмыс істемейтін уақытқа жазылу болмауы үшін" story "Given: иесі жексенбіні демалыс деп белгіледі. When: клиент жазылу бетін ашады. Then: жексенбіде бос слот көрсетілмейді."
mk "ZHL-14 Бизнес иесі ретінде келмей қалған клиенттер есебін алғым келеді, қай жерде шығын болатынын білу үшін" story "Given: кезең таңдалды. When: есеп құрылды. Then: жазылулар саны, келмей қалғандар саны мен үлесі, бас тартқандар саны көрсетілді."
mk "ZHL-15 ADR-002: технологиялық стекті таңдау" tech "Кемінде 2 нұсқаны салыстыру, клиенттердің дербес деректерінің (аты, телефоны) ҚР аумағында сақталуын ескеру."
mk "ZHL-16 Тапсыру журналына ЗС1 және ЗС2 жолдарын енгізу" docs "docs/wiki/05-tapsyru-zhurnaly.md"
echo "Дайын. Енді тақтада статустарды қой: ZHL-1, ZHL-3 → Done; ZHL-2 → Review; ZHL-4, ZHL-5 → In progress; ZHL-6, ZHL-16 → Ready."
